const input = $input.first().json;
const htmlData = (Array.isArray(input) ? input[0]?.data : input?.data) || '';

const regex = /data-post="([^"]+)"[\s\S]*?tgme_widget_message_text[^>]*>([\s\S]*?)<\/div>/; 
const match = regex.exec(htmlData);

if (!match) return [];

const currentPostId = match[1];
const staticData = $getWorkflowStaticData('node');

if (staticData.lastPostId === currentPostId) {
  return []; 
}
staticData.lastPostId = currentPostId;

let text = match[2]
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<[^>]+>/g, '')
  .replace(/&rlm;/gi, '') 
  .replace(/&\w+;/g, m => ({
    '&nbsp;': ' ', '&quot;': '"', '&amp;': '&',
    '&lt;': '<', '&gt;': '>', '&#39;': "'"
  }[m] || m))
  .replace(/\s+/g, ' ')
  .trim();

return [{
  json: {
    post_id: currentPostId,
    content: text,
    word_count: text.split(/\s+/).length,
    ready: true
  }
}];

